import math
import numpy as np
from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# One decision on entry, then every ten strategy calls (the simulator calls daily).
_call_count = 0
_last_rebalance = -1


def _ret(symbol, days):
    df = get_stock_daily_data(symbol=symbol, days=days + 8)
    if df is None or len(df) < days + 1:
        return None, None
    df = df.sort_values("date")
    close = np.asarray(df["close"], dtype=float)
    close = close[np.isfinite(close) & (close > 0)]
    if len(close) < days + 1:
        return None, None
    return float(close[-1] / close[-days-1] - 1.0), float(close[-1])


@register_hook
def cross_asset_reversal():
    global _call_count, _last_rebalance
    account = get_account_dict()
    _call_count += 1
    if _last_rebalance >= 0 and (_call_count - _last_rebalance) < 10:
        return
    watch = account.get("watch_list", [])
    # Keep the mandated universe, while tolerating an account response ordering change.
    universe = [s for s in ASSETS if s in watch] if watch else ASSETS
    if len(universe) != 15:
        universe = ASSETS

    values = {}
    prices = {}
    for s in universe:
        r, p = _ret(s, 5)
        if r is not None and p is not None:
            # Positive direction for the admitted reversal factor: recent losers rank high.
            values[s] = -r
            prices[s] = p
    if len(values) < 12:
        return

    # Cross-sectional rank score, clipped to limit the single-factor tail.
    ordered = sorted(values, key=values.get)
    ranks = {s: i / max(1, len(ordered)-1) for i, s in enumerate(ordered)}
    raw = {s: min(0.95, max(0.05, ranks.get(s, 0.5))) for s in universe}

    # Choppy/mildly bearish regime: modestly overweight defensive tradables.
    spx30, _ = _ret("SPX", 30)
    breadth = sum(1 for s in universe if values.get(s, 0) > 0) / float(len(values))
    defensive = {"XAU", "US10Y", "CN10Y"}
    if spx30 is not None and (spx30 < -0.015 or breadth < 0.35):
        for s in universe:
            if s in defensive:
                raw[s] *= 1.45
            elif s in {"BTC", "ETH", "SOX", "NDX", "WTI"}:
                raw[s] *= 0.75
    elif spx30 is not None and spx30 > 0.04 and breadth > 0.60:
        for s in universe:
            if s in defensive:
                raw[s] *= 0.85

    total = sum(raw.values())
    weights = {s: raw[s] / total for s in universe}
    # Complete vector invariant: no observation-only instruments and exact normalization.
    norm = sum(weights.values())
    weights = {s: max(0.0, weights[s] / norm) for s in universe}

    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    assets = float(account.get("total_assets", 0.0) or 0.0)
    targets = {s: assets * weights[s] for s in universe}
    current = {s: float(positions.get(s, {}).get("market_value", 0.0) or 0.0) for s in universe}

    # Reduce first, then add underweights. Fractional quantities are supported by benchmark.
    for s in universe:
        pos = positions.get(s)
        qty = float((pos or {}).get("quantity", 0) or 0)
        px = float((pos or {}).get("current_price", prices.get(s, 0)) or 0)
        if qty > 0 and px > 0 and current[s] > targets[s] * 1.002:
            add_order(symbol=s, order_type="SELL", price=px, quantity=min(qty, (current[s]-targets[s]) / px))
    for s in universe:
        px = prices.get(s, 0.0)
        if px <= 0:
            continue
        gap = targets[s] - current[s]
        if gap > max(assets * 0.001, 1.0):
            add_order(symbol=s, order_type="BUY", price=px, quantity=gap / px)
    _last_rebalance = _call_count

