import numpy as np
from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
_calls = 0
_last_decision = -10


def _series(symbol, days):
    df = get_stock_daily_data(symbol=symbol, days=days + 8)
    if df is None or len(df) < days + 1:
        return None
    x = np.asarray(df.sort_values("date")["close"], dtype=float)
    x = x[np.isfinite(x) & (x > 0)]
    return x if len(x) >= days + 1 else None


def _ret(symbol, days):
    x = _series(symbol, days)
    if x is None:
        return None, None
    return float(x[-1] / x[-days - 1] - 1.0), float(x[-1])


@register_hook
def cross_asset_reversal():
    global _calls, _last_decision
    _calls += 1
    account = get_account_dict()
    # Decisions are made every ten trading days; marks and pending orders continue daily.
    if _calls - _last_decision < 10:
        return
    watch = account.get("watch_list", [])
    universe = [s for s in ASSETS if s in watch] if watch else ASSETS
    if len(universe) != 15:
        universe = ASSETS

    # Do not stack orders while an earlier rebalance is pending.
    if account.get("orders"):
        return
    values, prices, vols = {}, {}, {}
    for s in universe:
        r, px = _ret(s, 5)
        x = _series(s, 20)
        if r is not None and px is not None and x is not None:
            values[s] = -r                 # admitted +direction reversal
            prices[s] = px
            vols[s] = max(float(np.std(np.diff(np.log(x[-21:]))) * np.sqrt(252)), 0.05)
    if len(values) < 12:
        return

    # Rank scores with a mild volatility risk control, retaining reversal as the signal.
    ordered = sorted(values, key=values.get)
    rank = {s: i / max(1, len(ordered) - 1) for i, s in enumerate(ordered)}
    raw = {s: 0.20 + 0.80 * rank.get(s, 0.5) for s in universe}
    median_vol = float(np.median(list(vols.values())))
    for s in vols:
        raw[s] *= min(1.20, max(0.75, median_vol / vols[s]))

    spx30, _ = _ret("SPX", 30)
    breadth = sum(values.get(s, 0.0) > 0 for s in universe) / float(len(values))
    defensive = {"XAU", "US10Y", "CN10Y"}
    risk_assets = {"BTC", "ETH", "SOX", "NDX", "WTI"}
    if (spx30 is not None and spx30 < -0.015) or breadth < 0.35:
        for s in universe:
            if s in defensive:
                raw[s] *= 1.35
            elif s in risk_assets:
                raw[s] *= 0.78
    elif spx30 is not None and spx30 > 0.04 and breadth > 0.60:
        for s in universe:
            if s in defensive:
                raw[s] *= 0.88

    total = sum(raw.values())
    weights = {s: raw[s] / total for s in universe}
    assets = float(account.get("total_assets", 0.0) or 0.0)
    positions = {p.get("symbol"): p for p in account.get("positions", [])}

    # Reduce overweight positions first. Integer quantities are required by the order API.
    for s in universe:
        p = positions.get(s, {})
        qty = max(0, int(float(p.get("quantity", 0) or 0)))
        px = float(p.get("current_price", prices.get(s, 0)) or 0)
        current = float(p.get("market_value", 0) or 0)
        target = assets * weights[s]
        if qty > 0 and px > 0 and current > target * 1.003:
            q = min(qty, int((current - target) / px))
            if q > 0:
                add_order(symbol=s, order_type="SELL", price=px, quantity=q)

    # Initial allocation is fully invested in the complete 15-asset tradable universe.
    # Subsequent buys use current marked value; proceeds from reductions become available next decision.
    for s in universe:
        px = float(prices.get(s, 0) or 0)
        if px <= 0:
            continue
        current = float(positions.get(s, {}).get("market_value", 0) or 0)
        gap = assets * weights[s] - current
        q = int(max(0.0, gap) / px)
        if q > 0:
            add_order(symbol=s, order_type="BUY", price=px, quantity=q)
    _last_decision = _calls

from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_index_daily_data, get_account_dict

# Complete-universe, long-only cross-sectional portfolio.
UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_day_count = 0
_last_target = None


def _symbol_list(raw):
    out = []
    for x in raw or []:
        s = x if isinstance(x, str) else x.get("symbol", x.get("code", ""))
        if s in UNIVERSE and s not in out:
            out.append(s)
    return out or list(UNIVERSE)


def _rank(values, descending=True):
    ordered = sorted(values, key=lambda z: z[1], reverse=descending)
    n = len(ordered)
    return {s: (n - i) / n for i, _ in enumerate(ordered)}


@register_hook
def cross_asset_rebalance():
    global _day_count, _last_target
    _day_count += 1
    if _day_count > 1 and (_day_count - 1) % 10 != 0:
        return

    account = get_account_dict() or {}
    symbols = _symbol_list(account.get("watch_list"))
    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    # Do not stack orders; an unfilled migration should be allowed to settle.
    if account.get("orders"):
        return

    rows = []
    for s in symbols:
        df = get_stock_daily_data(symbol=s, days=65)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date")
        close = [float(x) for x in df["close"].tolist() if x and x > 0]
        if len(close) < 25:
            continue
        r5 = close[-1] / close[-6] - 1.0
        r20 = close[-1] / close[-21] - 1.0
        daily = [close[i] / close[i-1] - 1.0 for i in range(max(1, len(close)-21), len(close))]
        vol = (sum((x - sum(daily)/len(daily))**2 for x in daily) / max(1, len(daily)-1)) ** 0.5
        rows.append((s, r5, r20, max(vol, 0.004), close[-1]))
    if len(rows) < 10:
        return

    # Screener ensemble: positive short-term reversal and risk-adjusted 20d momentum.
    rev = _rank([(s, -r5) for s, r5, _, _, _ in rows])
    mom = _rank([(s, r20 / v) for s, _, r20, v, _ in rows])
    invvol = _rank([(s, -v) for s, _, _, v, _ in rows])
    score = {s: 0.504 * rev[s] + 0.496 * mom[s] for s, *_ in rows}

    # Weak/sideways trend receives a modest defensive tilt, not cash.
    try:
        spx = get_index_daily_data(symbol="SPX", days=65)
        sc = [float(x) for x in spx.sort_values("date")["close"].tolist() if x and x > 0]
        weak = len(sc) >= 50 and (sc[-1] / sc[-21] - 1.0 < 0.01 or sc[-1] < sum(sc[-20:]) / 20.0)
    except Exception:
        weak = False
    if weak:
        for s in score:
            if s in DEFENSIVE:
                score[s] += 0.10
            elif s in {"BTC", "ETH", "SOX", "NDX", "WTI"}:
                score[s] -= 0.05

    # Broad allocation: score tilt plus inverse-volatility risk control, all 15 assets.
    raw = {}
    for s, _, _, v, _ in rows:
        raw[s] = max(0.02, (0.55 + score[s]) * (0.65 + 0.35 * invvol[s]))
    missing = set(symbols) - set(raw)
    for s in missing:
        raw[s] = 0.02
    total = sum(raw.values())
    target = {s: raw[s] / total for s in symbols}
    _last_target = target

    assets = float(account.get("total_assets", account.get("net_assets", 0)) or 0)
    if assets <= 0:
        return
    for s in symbols:
        pos = positions.get(s, {})
        qty = float(pos.get("quantity", 0) or 0)
        price = float(pos.get("current_price", 0) or 0)
        if price <= 0:
            price = next((r[4] for r in rows if r[0] == s), 0)
        if price <= 0:
            continue
        desired = assets * target[s] / price
        delta = desired - qty
        # Integer quantities are accepted by all simulator versions; residual is immaterial.
        if delta < -1:
            sellable = float(pos.get("available_quantity", qty) or qty)
            q = int(min(-delta, sellable))
            if q > 0:
                add_order(symbol=s, order_type="SELL", price=price, quantity=q)
        elif delta > 1:
            q = int(delta)
            if q > 0:
                add_order(symbol=s, order_type="BUY", price=price, quantity=q)

