from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, add_order
import math

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_last_rebalance = None


def _rank(values, reverse=True):
    order = sorted(values, key=lambda x: x[1], reverse=reverse)
    out = {}
    n = max(1, len(order) - 1)
    for i, (s, _) in enumerate(order):
        out[s] = 1.0 - i / n if reverse else i / n
    return out


@register_hook
def cross_asset_strategy():
    global _last_rebalance
    account = get_account_dict()
    watch = [s for s in UNIVERSE if s in (account.get("watch_list") or UNIVERSE)]
    if len(watch) != 15:
        watch = list(UNIVERSE)
    positions = {p.get("symbol"): p for p in account.get("positions", []) if p.get("quantity", 0) > 0}
    pending = account.get("orders", [])
    # Do not duplicate the initial allocation while orders are awaiting execution.
    if not positions and pending:
        return

    data = {}
    for symbol in watch:
        df = get_stock_daily_data(symbol=symbol, days=75)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        closes = [float(x) for x in df["close"].tolist() if x is not None and float(x) > 0]
        if len(closes) < 30:
            continue
        r5 = closes[-1] / closes[-6] - 1.0
        r20 = closes[-1] / closes[-21] - 1.0
        rets = [closes[i] / closes[i-1] - 1.0 for i in range(max(1, len(closes)-20), len(closes))]
        vol = math.sqrt(sum((r - sum(rets)/len(rets))**2 for r in rets) / max(1, len(rets)-1))
        data[symbol] = {"price": closes[-1], "rev": -r5, "mom": r20 / max(vol, 0.006), "vol": max(vol, 0.006)}
    if len(data) < 12:
        return

    # Rebalance on the first online day and then at a ten-trading-day cadence.
    current_date = str(get_stock_daily_data(symbol="SPX", days=2).sort_values("date").iloc[-1]["date"])
    if _last_rebalance is not None:
        spx = get_stock_daily_data(symbol="SPX", days=30)
        dates = [str(x) for x in spx.sort_values("date")["date"].tolist()]
        if current_date in dates and str(_last_rebalance) in dates:
            if dates.index(current_date) - dates.index(str(_last_rebalance)) < 10:
                return
    rev_rank = _rank([(s, v["rev"]) for s, v in data.items()], True)
    mom_rank = _rank([(s, v["mom"]) for s, v in data.items()], True)

    # Sideways/mildly bearish regime: broad portfolio, with a modest defensive tilt.
    spx_df = get_stock_daily_data(symbol="SPX", days=70)
    bearish = False
    if spx_df is not None and len(spx_df) >= 45:
        c = [float(x) for x in spx_df.sort_values("date")["close"].tolist()]
        bearish = c[-1] < c[-21] and c[-1] < c[-41]
    raw = {}
    for s, v in data.items():
        score = 0.504 * rev_rank[s] + 0.496 * mom_rank[s]
        # inverse volatility limits concentration without discarding the ensemble
        raw[s] = max(0.02, score + 0.18 / (1.0 + 30.0 * v["vol"]))
        if bearish and s in DEFENSIVE:
            raw[s] *= 1.18
    total = sum(raw.values())
    weights = {s: raw.get(s, 0.0) / total for s in watch}
    # Missing data receive a small diversified allocation; renormalize exactly.
    z = sum(weights.values())
    weights = {s: weights[s] / z for s in watch}

    assets = float(account.get("total_assets", 0) or account.get("net_assets", 0))
    if assets <= 0:
        return
    for s in watch:
        if s not in data:
            continue
        price = data[s]["price"]
        old_qty = float(positions.get(s, {}).get("quantity", 0) or 0)
        old_value = old_qty * price
        target_value = assets * weights[s]
        delta = target_value - old_value
        # Avoid churning immaterial transfers; all submitted quantities are fractional-valid.
        if abs(delta) < assets * 0.003:
            continue
        qty = abs(delta) / price
        if qty <= 0:
            continue
        add_order(symbol=s, order_type="BUY" if delta > 0 else "SELL", price=price, quantity=qty)
    _last_rebalance = current_date

