DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
FACTOR_WEIGHTS = (0.504, 0.496)  # 5d reversal, 20d risk-adjusted momentum
REBALANCE_DAYS = 10
MIGRATION_THRESHOLD = 0.001  # avoid noise, while retaining a complete invested target
_last_rebalance_date = None


def _rank(values):
    ordered = sorted(values, key=lambda z: z[1], reverse=True)
    n = max(1, len(ordered) - 1)
    return {s: 1.0 - i / n for i, (s, _) in enumerate(ordered)}


def _date_key(v):
    return str(v)[:10]


@register_hook
def cross_asset_strategy():
    global _last_rebalance_date
    account = get_account_dict()
    listed = set(account.get("watch_list") or UNIVERSE)
    watch = [s for s in UNIVERSE if s in listed]
    if len(watch) != 15:
        watch = list(UNIVERSE)
    # Never compound orders from an unfinished rebalance.
    if account.get("orders"):
        return

    series = {}
    for symbol in watch:
        df = get_stock_daily_data(symbol=symbol, days=75)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = [float(v) for v in df["close"] if v is not None and float(v) > 0]
        if len(close) < 22:
            continue
        rets = [close[i] / close[i - 1] - 1.0 for i in range(max(1, len(close) - 20), len(close))]
        avg = sum(rets) / len(rets)
        vol = math.sqrt(sum((r - avg) ** 2 for r in rets) / max(1, len(rets) - 1))
        series[symbol] = {
            "price": close[-1],
            "reversal": -(close[-1] / close[-6] - 1.0),
            "momentum": (close[-1] / close[-21] - 1.0) / max(vol, 0.006),
            "vol": max(vol, 0.006),
        }
    if len(series) < 12:
        return

    spx = get_stock_daily_data(symbol="SPX", days=70)
    bearish = False
    if spx is not None and len(spx) >= 45:
        c = [float(v) for v in spx.sort_values("date")["close"] if float(v) > 0]
        bearish = len(c) >= 45 and c[-1] < c[-21] and c[-1] < c[-41]

    # Decisions are made from the last completed bar; cadence is trading-day based.
    decision_date = _date_key(get_stock_daily_data("SPX", 2).sort_values("date").iloc[-1]["date"])
    if _last_rebalance_date is not None:
        hist = [_date_key(v) for v in get_stock_daily_data("SPX", 30).sort_values("date")["date"]]
        if _last_rebalance_date in hist and decision_date in hist:
            if hist.index(decision_date) - hist.index(_last_rebalance_date) < REBALANCE_DAYS:
                return

    reversal_rank = _rank([(s, x["reversal"]) for s, x in series.items()])
    momentum_rank = _rank([(s, x["momentum"]) for s, x in series.items()])
    invvol_sum = sum(1.0 / x["vol"] for x in series.values())
    raw = {}
    for s in watch:
        if s in series:
            x = series[s]
            factor_score = FACTOR_WEIGHTS[0] * reversal_rank[s] + FACTOR_WEIGHTS[1] * momentum_rank[s]
            invvol_share = (1.0 / x["vol"]) / invvol_sum
            raw[s] = 0.60 * factor_score + 0.40 * invvol_share
        else:
            raw[s] = 0.01
        # Mild-bearish regime is expressed with tradable defensive assets, not cash.
        if bearish and s in DEFENSIVE:
            raw[s] *= 1.15
    total = sum(max(0.0, raw[s]) for s in watch)
    weights = {s: max(0.0, raw[s]) / total for s in watch}

    assets = float(account.get("total_assets", 0) or account.get("net_assets", 0))
    if assets <= 0:
        return
    positions = {p.get("symbol"): p for p in account.get("positions", [])
                 if float(p.get("quantity", 0) or 0) > 0}

    # Target is defined for every tradable asset. Fractional quantities are valid.
    # The small threshold limits turnover but does not create a cash sleeve on initial allocation.
    initial = not positions
    for s in watch:
        px = series.get(s, {}).get("price", 0.0)
        if px <= 0:
            continue
        held = float(positions.get(s, {}).get("quantity", 0) or 0)
        delta_value = assets * weights[s] - held * px
        if not initial and abs(delta_value) < assets * MIGRATION_THRESHOLD:
            continue
        quantity = abs(delta_value) / px
        if quantity > 1e-9:
            add_order(symbol=s, order_type="BUY" if delta_value > 0 else "SELL",
                      price=px, quantity=quantity)
    _last_rebalance_date = decision_date

