    return {s: 1.0 - i / n for i, (_, s) in enumerate([(v, k) for k, v in ordered])}


def _date(x):
    return str(x)[:10]


@register_hook
def cross_asset_strategy():
    global _last_rebalance_date
    account = get_account_dict()
    listed = set(account.get("watch_list") or [])
    watch = [s for s in UNIVERSE if s in listed] if listed else UNIVERSE
    if set(watch) != set(UNIVERSE):
        return
    # Avoid overlapping orders; they are settled/processed by the simulator.
