        data[s] = {"price": close[-1], "r5": close[-1] / close[-6] - 1.0,
                   "mom": (close[-1] / close[-21] - 1.0) / vol,
                   "vol": vol, "ret5": close[-1] / close[-6] - 1.0}

    # Leave-one-out peer median lead-lag: today's asset return versus peer median.
    for s in watch:
        peers = sorted(data[x]["ret5"] for x in watch if x != s)
