        raw[s] = 0.60*score + 0.40*inv[s]/inv_total
        if bearish and s in DEFENSIVE:
            raw[s] *= 1.15
    total = sum(raw.values())
    weights = {s: raw[s]/total for s in watch}

    assets = float(account.get("total_assets", 0) or account.get("net_assets", 0))
    if assets <= 0:
        return
    positions = {p.get("symbol"): p for p in account.get("positions", [])
                 if float(p.get("quantity", 0) or 0) > 0}
    initial = not positions
    for s in watch:
        px = data[s]["price"]
        held = float(positions.get(s, {}).get("quantity", 0) or 0)
        delta = assets*weights[s] - held*px
        if not initial and abs(delta) < assets*MIGRATION_THRESHOLD:
            continue
        qty = abs(delta) / px
        if qty > 1e-9:
            add_order(symbol=s, order_type="BUY" if delta > 0 else "SELL", price=px, quantity=qty)
    _last_rebalance_date = decision

