from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, add_order
import math

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
# factor_ensemble.json: peer lead-lag 39.5%, 5d reversal 30.5%,
# risk-adjusted 20d momentum 30.0%; all directions are positive.
FACTOR_WEIGHTS = (0.395, 0.305, 0.300)
REBALANCE_DAYS = 10
MIGRATION_THRESHOLD = 0.001
_last_rebalance_date = None


def _clean_prices(df):
    df = df.sort_values("date").reset_index(drop=True)
    return [float(x) for x in df["close"] if x is not None and float(x) > 0]


def _rank(values, descending=True):
    ordered = sorted(values.items(), key=lambda z: z[1], reverse=descending)
    n = max(1, len(ordered) - 1)
    return {symbol: 1.0 - i / n for i, (symbol, _) in enumerate(ordered)}


def _day(x):
    return str(x)[:10]


@register_hook
def cross_asset_strategy():
    global _last_rebalance_date
    account = get_account_dict()
    listed = set(account.get("watch_list") or [])
    if listed and listed != set(UNIVERSE):
        return
    watch = UNIVERSE
    # Never add to an already pending rebalance.
    if account.get("orders"):
        return

    data = {}
    for symbol in watch:
        df = get_stock_daily_data(symbol=symbol, days=80)
        if df is None or len(df) < 45:
            return
        close = _clean_prices(df)
        if len(close) < 45:
            return
        r5 = close[-1] / close[-6] - 1.0
        r20 = [close[i] / close[i - 1] - 1.0 for i in range(len(close) - 20, len(close))]
        mean = sum(r20) / len(r20)
        vol = max(math.sqrt(sum((r - mean) ** 2 for r in r20) / max(1, len(r20) - 1)), 0.006)
        data[symbol] = {"price": close[-1], "r5": r5, "mom": (close[-1] / close[-21] - 1.0) / vol, "vol": vol}

    # Peer-median lead-lag: the peer five-day move is the predictor for this asset.
    for symbol in watch:
        peer_returns = sorted(data[x]["r5"] for x in watch if x != symbol)
        data[symbol]["lead"] = peer_returns[len(peer_returns) // 2]

    lead = _rank({s: data[s]["lead"] for s in watch})
    # Positive ensemble direction applied to the reversal transformation (- five-day return).
    reversal = _rank({s: -data[s]["r5"] for s in watch})
    momentum = _rank({s: data[s]["mom"] for s in watch})

    spx_df = get_stock_daily_data(symbol="SPX", days=70)
    if spx_df is None or len(spx_df) < 45:
        return
    spx_df = spx_df.sort_values("date").reset_index(drop=True)
    spx = _clean_prices(spx_df)
    if len(spx) < 45:
        return
    decision = _day(spx_df.iloc[-1]["date"])
    if _last_rebalance_date is not None:
        dates = [_day(x) for x in spx_df["date"]]
        if _last_rebalance_date in dates and dates.index(decision) - dates.index(_last_rebalance_date) < REBALANCE_DAYS:
            return

    bearish = spx[-1] < spx[-21] and spx[-1] < spx[-41]
    inv_vol = {s: 1.0 / data[s]["vol"] for s in watch}
    inv_total = sum(inv_vol.values())
    raw = {}
    for s in watch:
        signal = FACTOR_WEIGHTS[0] * lead[s] + FACTOR_WEIGHTS[1] * reversal[s] + FACTOR_WEIGHTS[2] * momentum[s]
        raw[s] = 0.60 * signal + 0.40 * inv_vol[s] / inv_total
        if bearish and s in DEFENSIVE:
            raw[s] *= 1.15
    total = sum(raw.values())
    weights = {s: raw[s] / total for s in watch}  # complete, non-negative, sums to one

    assets = float(account.get("total_assets", 0) or account.get("net_assets", 0))
    if assets <= 0:
        return
    positions = {p.get("symbol"): p for p in account.get("positions", []) if float(p.get("quantity", 0) or 0) > 0}
    initial = not positions
    for s in watch:
        px = data[s]["price"]
        held_value = float(positions.get(s, {}).get("quantity", 0) or 0) * px
        delta = assets * weights[s] - held_value
        if not initial and abs(delta) < assets * MIGRATION_THRESHOLD:
            continue
        quantity = int(abs(delta) / px)  # fractional quantities are allowed; no board-lot rounding
        if quantity > 0:
            add_order(symbol=s, order_type="BUY" if delta > 0 else "SELL", price=px, quantity=quantity)
    _last_rebalance_date = decision

