from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

# Conservative cross-asset, long-only full-investment allocator.
UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_EVERY = 10
MAX_WEIGHT = 0.18
MIN_WEIGHT = 0.025
# Hook is called once per trading day; these persist for the simulation process.
_call_count = 0
_last_rebalance = None


def _rank(values, reverse=True):
    ordered = sorted(values, key=lambda x: x[1], reverse=reverse)
    n = len(ordered)
    return {s: (n - 1 - i) / max(1, n - 1) for i, (s, _) in enumerate(ordered)}


@register_hook
def cross_asset_strategy():
    global _call_count, _last_rebalance
    _call_count += 1
    account = get_account_dict() or {}
    # Use the specified benchmark universe, not observation-only macro series.
    watch = [s for s in UNIVERSE if s in (account.get("watch_list") or UNIVERSE)]
    if len(watch) != 15:
        watch = list(UNIVERSE)
    if _call_count != 1 and (_call_count - 1) % REBALANCE_EVERY != 0:
        return

    histories = {}
    for symbol in watch:
        df = get_stock_daily_data(symbol=symbol, days=75)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date")
        closes = [float(x) for x in df["close"].tolist() if x == x and x > 0]
        if len(closes) >= 25:
            histories[symbol] = closes
    if len(histories) < 10:
        return

    # Cross-sectional factor approximations, using only completed observations.
    r5 = {s: p[-1] / p[-6] - 1.0 for s, p in histories.items() if len(p) >= 6}
    r20 = {s: p[-1] / p[-21] - 1.0 for s, p in histories.items() if len(p) >= 21}
    vol = {}
    for s, p in histories.items():
        rets = [p[i] / p[i-1] - 1.0 for i in range(max(1, len(p)-20), len(p))]
        if len(rets) >= 10:
            mean = sum(rets) / len(rets)
            vv = sum((x - mean) ** 2 for x in rets) / len(rets)
            vol[s] = max(vv ** 0.5, 0.005)
    common = [s for s in watch if s in r5 and s in r20 and s in vol]
    if len(common) < 10:
        return
    peer_median = sorted(r5[s] for s in common)[len(common)//2]
    # Lead-lag is smoothed toward the peer median; reversal is inverse recent return.
    lead = {s: 0.5 * r5[s] + 0.5 * peer_median for s in common}
    reversal = {s: -r5[s] for s in common}
    momentum = {s: r20[s] / vol[s] for s in common}
    ranks = [_rank([(s, lead[s]) for s in common]),
             _rank([(s, reversal[s]) for s in common]),
             _rank([(s, momentum[s]) for s in common])]
    signal = {s: 0.395*ranks[0][s] + 0.305*ranks[1][s] + 0.300*ranks[2][s] for s in common}
    invvol = {s: 1.0 / vol[s] for s in common}
    ivr = _rank([(s, invvol[s]) for s in common])

    # 60% factor rank / 40% inverse-volatility, with defensive rotation in weak SPX.
    spx_bear = "SPX" in histories and len(histories["SPX"]) >= 31 and histories["SPX"][-1] < histories["SPX"][-31]
    raw = {}
    for s in common:
        raw[s] = 0.60 * signal[s] + 0.40 * ivr[s] + 0.20
        if spx_bear and s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.15
    total = sum(raw.values())
    weights = {s: raw[s] / total for s in common}
    # Give every benchmark asset a small, positive allocation and cap concentration.
    for s in watch:
        weights.setdefault(s, MIN_WEIGHT)
    z = sum(weights.values())
    weights = {s: w / z for s, w in weights.items()}
    for _ in range(5):
        over = sum(max(0.0, w - MAX_WEIGHT) for w in weights.values())
        if over <= 1e-10:
            break
        under = [s for s, w in weights.items() if w < MAX_WEIGHT - 1e-10]
        for s in list(weights):
            if weights[s] > MAX_WEIGHT:
                weights[s] = MAX_WEIGHT
        if under:
            add = over / len(under)
            for s in under:
                weights[s] += add
    weights = {s: max(0.0, w) for s, w in weights.items()}
    norm = sum(weights.values())
    weights = {s: w / norm for s, w in weights.items()}

    positions = {p.get("symbol"): p for p in account.get("positions", []) if p.get("quantity", 0) > 0}
    prices = {s: histories[s][-1] for s in common}
    assets = float(account.get("total_assets", 0) or 0)
    if assets <= 0:
        return
    # Existing pending orders are left alone; avoid stacking duplicate rebalance orders.
    if account.get("orders"):
        return
    for s, p in positions.items():
        if s not in weights or s not in prices:
            continue
        current = float(p.get("market_value", 0) or 0)
        target = assets * weights[s]
        if current > target * 1.001:
            qty = min(float(p.get("available_quantity", p.get("quantity", 0))), (current-target)/prices[s])
            if qty > 1e-8:
                add_order(symbol=s, order_type="SELL", price=prices[s], quantity=qty)
    for s in common:
        current = float(positions.get(s, {}).get("market_value", 0) or 0)
        delta = assets * weights[s] - current
        if delta > assets * 0.001:
            add_order(symbol=s, order_type="BUY", price=prices[s], quantity=delta/prices[s])
    _last_rebalance = _call_count

