import math
import numpy as np
from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
REBALANCE_DAYS = 10
MAX_WEIGHT = 0.18
MIN_WEIGHT = 0.012
FACTOR_W = (0.395, 0.305, 0.300)
_day = 0


def rank(values):
    finite = [v for v in values.values() if np.isfinite(v)]
    if not finite:
        return {s: 0.5 for s in values}
    n = len(finite)
    return {s: (0.5 if not np.isfinite(v) else sum(x <= v for x in finite) / n)
            for s, v in values.items()}


def capped_weights(raw):
    """Normalize positive scores to a valid capped simplex."""
    w = {s: max(MIN_WEIGHT, float(v)) for s, v in raw.items()}
    for _ in range(30):
        total = sum(w.values())
        if total <= 0:
            w = {s: 1.0 / len(w) for s in w}
            break
        w = {s: min(MAX_WEIGHT, v / total) for s, v in w.items()}
        excess = 1.0 - sum(w.values())
        free = [s for s in w if w[s] < MAX_WEIGHT - 1e-9]
        if excess <= 1e-9 or not free:
            break
        for s in free:
            w[s] += excess / len(free)
    total = sum(w.values())
    return {s: v / total for s, v in w.items()}


@register_hook
def cross_asset_allocator():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS != 0:
        return

    account = get_account_dict()
    # Deliberately use the fixed benchmark universe; observation-only macro
    # identifiers can never enter this list.
    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=75)
        if df is not None and len(df) >= 25:
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if np.all(np.isfinite(p)) and p[-1] > 0:
                closes[symbol] = p
    if len(closes) < 8:
        return

    r5, r20, vol = {}, {}, {}
    for s in UNIVERSE:
        p = closes.get(s)
        if p is None or len(p) < 25 or p[-21] <= 0 or p[-6] <= 0:
            r5[s] = r20[s] = vol[s] = np.nan
            continue
        daily = p[1:] / p[:-1] - 1.0
        r5[s] = p[-1] / p[-6] - 1.0
        r20[s] = p[-1] / p[-21] - 1.0
        vol[s] = max(np.std(daily[-20:]) * math.sqrt(252), 0.05)

    peers = [r5[s] for s in UNIVERSE if np.isfinite(r5[s])]
    median5 = float(np.median(peers)) if peers else 0.0
    # Positive lead-lag direction favors recent relative leaders; positive
    # reversal direction favors recent laggards.
    lead = {s: (r5[s] - median5 if np.isfinite(r5[s]) else np.nan) for s in UNIVERSE}
    reversal = {s: (-r5[s] if np.isfinite(r5[s]) else np.nan) for s in UNIVERSE}
    risk_mom = {s: (r20[s] / vol[s] if np.isfinite(r20[s]) and np.isfinite(vol[s]) else np.nan) for s in UNIVERSE}
    invvol = {s: (1.0 / vol[s] if np.isfinite(vol[s]) else np.nan) for s in UNIVERSE}
    lr, rr, mr = rank(lead), rank(reversal), rank(risk_mom)

    spx = closes.get("SPX")
    bearish = bool(spx is not None and len(spx) >= 31 and spx[-1] / spx[-31] < 0.995)
    raw = {}
    for s in UNIVERSE:
        # Missing data gets neutral ranks and remains invested at the floor.
        signal = FACTOR_W[0] * lr[s] + FACTOR_W[1] * rr[s] + FACTOR_W[2] * mr[s]
        lowrisk = rank(invvol)[s]
        score = 0.45 * signal + 0.55 * lowrisk
        if bearish and s in DEFENSIVE:
            score += 0.18
        if np.isfinite(vol.get(s, np.nan)) and vol[s] > 0.75:
            score *= 0.88
        raw[s] = MIN_WEIGHT + max(score, 0.0)
    weights = capped_weights(raw)

    assets = float(account.get("total_assets", 0.0) or 0.0)
    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    prices = {s: float((positions.get(s) or {}).get("current_price", 0) or closes.get(s, [0])[-1]) for s in UNIVERSE}
    # Fractional quantities are supported by the benchmark. Submit only
    # meaningful deltas, and sell before buying to avoid transient leverage.
    targets = {s: assets * weights[s] / prices[s] for s in UNIVERSE if prices[s] > 0}
    for s, target in targets.items():
        current = float((positions.get(s) or {}).get("quantity", 0) or 0)
        if current - target > 1e-8:
            add_order(symbol=s, order_type="SELL", price=prices[s], quantity=current - target)
    for s, target in targets.items():
        current = float((positions.get(s) or {}).get("quantity", 0) or 0)
        if target - current > 1e-8:
            add_order(symbol=s, order_type="BUY", price=prices[s], quantity=target - current)

