import math
import numpy as np
from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
REBALANCE_DAYS = 10
MIN_WEIGHT = 0.012
MAX_WEIGHT = 0.18
FACTOR_WEIGHTS = (0.395, 0.305, 0.300)
_day = 0


def percentile_rank(values):
    good = [v for v in values.values() if np.isfinite(v)]
    if not good:
        return {s: 0.5 for s in values}
    n = len(good)
    return {s: (sum(x <= v for x in good) / n if np.isfinite(v) else 0.5)
            for s, v in values.items()}


def normalize_weights(raw):
    # Iterative floor/cap projection, retaining a complete 15-asset portfolio.
    w = {s: max(MIN_WEIGHT, float(raw.get(s, MIN_WEIGHT))) for s in UNIVERSE}
    for _ in range(50):
        total = sum(w.values())
        w = {s: min(MAX_WEIGHT, x / total) for s, x in w.items()}
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if w[s] < MAX_WEIGHT - 1e-10]
        if gap <= 1e-10 or not free:
            break
        for s in free:
            w[s] += gap / len(free)
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_allocator():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS != 0:
        return

    account = get_account_dict()
    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=80)
        if df is None or len(df) < 25:
            continue
        p = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(p) >= 25 and np.all(np.isfinite(p)) and np.all(p > 0):
            closes[symbol] = p

    # Missing observations receive neutral factor ranks, but still get a target.
    r5, r20, vol = {}, {}, {}
    for symbol in UNIVERSE:
        p = closes.get(symbol)
        if p is None or len(p) < 25:
            r5[symbol] = r20[symbol] = vol[symbol] = np.nan
            continue
        d = p[1:] / p[:-1] - 1.0
        r5[symbol] = p[-1] / p[-6] - 1.0
        r20[symbol] = p[-1] / p[-21] - 1.0
        vol[symbol] = max(float(np.std(d[-20:]) * math.sqrt(252)), 0.05)

    peer_returns = [r5[s] for s in UNIVERSE if np.isfinite(r5[s])]
    median5 = float(np.median(peer_returns)) if peer_returns else 0.0
    # Both selected short-horizon factors are implemented as laggard/reversal
    # ranks; the 20-day factor supplies the slower diversification sleeve.
    leadlag = {s: (median5 - r5[s] if np.isfinite(r5[s]) else np.nan) for s in UNIVERSE}
    reversal = {s: (-r5[s] if np.isfinite(r5[s]) else np.nan) for s in UNIVERSE}
    risk_momentum = {s: (r20[s] / vol[s] if np.isfinite(r20[s]) and np.isfinite(vol[s]) else np.nan) for s in UNIVERSE}
    invvol = {s: (1.0 / vol[s] if np.isfinite(vol[s]) else np.nan) for s in UNIVERSE}
    a, b, c, v = (percentile_rank(x) for x in (leadlag, reversal, risk_momentum, invvol))

    spx = closes.get("SPX")
    bearish = bool(spx is not None and len(spx) >= 31 and spx[-1] / spx[-31] < 0.995)
    raw = {}
    for s in UNIVERSE:
        factor_score = FACTOR_WEIGHTS[0] * a[s] + FACTOR_WEIGHTS[1] * b[s] + FACTOR_WEIGHTS[2] * c[s]
        # Volatility is a risk control, not a fourth alpha factor.
        score = 0.75 * factor_score + 0.25 * v[s]
        if np.isfinite(vol[s]) and vol[s] > 0.75:
            score *= 0.88
        if bearish and s in DEFENSIVE:
            score += 0.14
        raw[s] = MIN_WEIGHT + max(score, 0.0)
    weights = normalize_weights(raw)

    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    total_assets = float(account.get("total_assets", 0.0) or 0.0)
    prices = {}
    for s in UNIVERSE:
        pos = positions.get(s, {})
        px = float(pos.get("current_price", 0) or 0)
        if px <= 0 and s in closes:
            px = float(closes[s][-1])
        if px > 0:
            prices[s] = px

    # Sell first to fund increases; fractional quantities are supported by the
    # benchmark, while integer quantities remain accepted by older adapters.
    targets = {s: total_assets * weights[s] / prices[s] for s in prices}
    for s, target in targets.items():
        current = float((positions.get(s) or {}).get("quantity", 0) or 0)
        if current > target + 1e-8:
            add_order(symbol=s, order_type="SELL", price=prices[s], quantity=current - target)
    for s, target in targets.items():
        current = float((positions.get(s) or {}).get("quantity", 0) or 0)
        if target > current + 1e-8:
            add_order(symbol=s, order_type="BUY", price=prices[s], quantity=target - current)

