    with open("factors/factor_ensemble.json", "r", encoding="utf-8") as f:
        _ensemble = json.load(f).get("selected_factors", [])[:10]
except Exception:
    _ensemble = []
FACTOR_WEIGHTS = {x.get("factor_id"): float(x.get("weight", 0.0)) * float(x.get("direction", 1)) for x in _ensemble}
