    with open("factors/factor_ensemble.json", "r", encoding="utf-8") as f:
        selected = json.load(f).get("selected_factors", [])[:10]
    if selected:
        FACTOR_WEIGHTS = {x["factor_id"]: float(x.get("weight", 0.0)) * float(x.get("direction", 1)) for x in selected}
except Exception:
    pass
_day = 0

def rank01(values):
    good = [v for v in values.values() if np.isfinite(v)]
    if not good:
        return {s: .5 for s in UNIVERSE}
    return {s: (sum(v <= values[s] for v in good) / len(good) if np.isfinite(values[s]) else .5) for s in UNIVERSE}

def bounded_weights(scores):
    # Projection-like water filling: all names remain invested, with explicit bounds.
    w = {s: MIN_WEIGHT for s in UNIVERSE}
    remaining = 1.0 - sum(w.values())
    positive = {s: max(float(scores.get(s, .5)), 1e-6) for s in UNIVERSE}
