import json
import math
import numpy as np
from alphacrafter.sim.utils import register_hook, add_order, get_stock_daily_data, get_account_dict

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.015, 0.16
SIGNAL_MIX, RISK_MIX = 0.78, 0.22
FACTORS = {
    "miner_3_clv_1d": 0.3395,
    "peer_median_leadlag_5d": 0.2612,
    "short_term_reversal_5d": 0.2012,
    "miner_2_risk_adjusted_momentum_20d": 0.1981,
}
try:
    with open("factors/factor_ensemble.json", encoding="utf-8") as f:
        selected = json.load(f).get("selected_factors", [])[:10]
    if selected:
        FACTORS = {x["factor_id"]: float(x.get("weight", 0.0)) * float(x.get("direction", 1)) for x in selected}
except Exception:
    pass

_day = 0

def percentile(values):
    finite = sorted(float(x) for x in values.values() if np.isfinite(x))
    n = len(finite)
    if not n:
        return {s: 0.5 for s in UNIVERSE}
    return {s: (sum(v <= float(values.get(s, np.nan)) for v in finite) / n
                if np.isfinite(values.get(s, np.nan)) else 0.5) for s in UNIVERSE}

def bounded_weights(score):
    weights = {s: MIN_W for s in UNIVERSE}
    remaining = 1.0 - len(UNIVERSE) * MIN_W
    active = set(UNIVERSE)
    while active and remaining > 1e-10:
        positive = {s: max(float(score[s]), 1e-8) for s in active}
        total = sum(positive.values())
        capped = [s for s in active if remaining * positive[s] / total > MAX_W - MIN_W]
        if not capped:
            for s in active:
                weights[s] += remaining * positive[s] / total
            break
        for s in capped:
            weights[s] = MAX_W
            remaining -= MAX_W - MIN_W
            active.remove(s)
    norm = sum(weights.values())
    return {s: weights[s] / norm for s in UNIVERSE}

@register_hook
def cross_asset_allocator():
    global _day
    _day += 1
    if (_day - 1) % CADENCE != 0:
        return
    account = get_account_dict()
    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    prices, vols, clv, ret5, ret20, ret40 = {}, {}, {}, {}, {}, {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=130)
        if df is None or len(df) < 45:
            continue
        df = df.sort_values("date")
        p = np.asarray(df["close"], dtype=float)
        if len(p) < 42 or not np.all(np.isfinite(p[-42:])) or np.any(p[-42:] <= 0):
            continue
        prices[symbol] = float(p[-1])
        daily = p[1:] / p[:-1] - 1.0
        vols[symbol] = max(float(np.std(daily[-20:]) * math.sqrt(252)), 0.05)
        high, low = float(df.iloc[-1]["high"]), float(df.iloc[-1]["low"])
        clv[symbol] = (2.0 * p[-1] - high - low) / (high - low) if high > low else 0.0
        ret5[symbol] = p[-1] / p[-6] - 1.0
        ret20[symbol] = p[-1] / p[-21] - 1.0
        ret40[symbol] = p[-1] / p[-41] - 1.0
    if not prices:
        return
    median5 = float(np.median(list(ret5.values())))
    raw = {
        "miner_3_clv_1d": clv,
        "peer_median_leadlag_5d": {s: ret5.get(s, np.nan) - median5 for s in UNIVERSE},
        "short_term_reversal_5d": {s: -ret5.get(s, np.nan) for s in UNIVERSE},
        "miner_2_risk_adjusted_momentum_20d": {s: (0.5 * ret20[s] + 0.5 * ret40[s]) / vols[s] if s in prices else np.nan for s in UNIVERSE},
    }
    ranks = {factor: percentile(values) for factor, values in raw.items()}
    invvol = percentile({s: 1.0 / vols.get(s, 0.5) for s in UNIVERSE})
    spx = ret20.get("SPX", 0.0)
    bearish = spx < -0.005
    scores = {}
    for s in UNIVERSE:
        signal = sum(FACTORS.get(f, 0.0) * ranks[f][s] for f in raw)
        risk = invvol[s] * (0.88 if vols.get(s, 0.5) > 0.75 else 1.0)
        defensive = 0.10 if bearish and s in DEFENSIVE else 0.0
        scores[s] = max(SIGNAL_MIX * signal + RISK_MIX * risk + defensive, 1e-8)
    target = bounded_weights(scores)
    total = float(account.get("total_assets", 0.0) or 0.0)
    for s in UNIVERSE:
        price = prices.get(s, float((positions.get(s) or {}).get("current_price", 0.0) or 0.0))
        if price <= 0 or total <= 0:
            continue
        pos = positions.get(s) or {}
        current = float(pos.get("quantity", 0.0) or 0.0)
        available = float(pos.get("available_quantity", current) or 0.0)
        delta = total * target[s] / price - current
        if delta < 0 and available > 0:
            add_order(symbol=s, order_type="SELL", price=price, quantity=min(-delta, available))
    for s in UNIVERSE:
        price = prices.get(s, float((positions.get(s) or {}).get("current_price", 0.0) or 0.0))
        if price <= 0 or total <= 0:
            continue
        current = float((positions.get(s) or {}).get("quantity", 0.0) or 0.0)
        delta = total * target[s] / price - current
        if delta > 0:
            add_order(symbol=s, order_type="BUY", price=price, quantity=delta)

