import math
import json
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_account_dict, add_order

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_DAYS = 10
_last_decision = None

try:
    with open("factors/factor_ensemble.json", "r", encoding="utf-8") as f:
        ENSEMBLE = json.load(f).get("selected_factors", [])[:10]
except Exception:
    ENSEMBLE = []


def _rank(values, reverse=False):
    keys = sorted(values, key=values.get, reverse=reverse)
    n = max(1, len(keys) - 1)
    return {s: i / n for i, s in enumerate(keys)}


def _data(symbol, days=80):
    try:
        return get_stock_daily_data(symbol=symbol, days=days)
    except Exception:
        return None


def _weights(series):
    # Cross-sectional rank composite, then blend with a stable inverse-volatility overlay.
    symbols = list(series)
    ranks = {}
    for fid in [x.get("factor_id") for x in ENSEMBLE]:
        vals = {s: series[s][fid] for s in symbols if fid in series[s] and math.isfinite(series[s][fid])}
        if not vals:
            continue
        rr = _rank(vals)
        for s, v in rr.items():
            ranks.setdefault(s, 0.5)
            wt = next(x.get("weight", 0) for x in ENSEMBLE if x.get("factor_id") == fid)
            ranks[s] += wt * v
    # The defensive sleeve is a tradable tilt, not cash, in weak broad-market trend.
    spx = series.get("SPX", {})
    weak = spx.get("spx20", 0.0) < 0 and spx.get("spx60", 0.0) < 0
    if weak:
        for s in symbols:
            if s in ("XAU", "US10Y", "CN10Y"):
                ranks[s] = ranks.get(s, 0.5) + 0.10
            if s in ("BTC", "ETH", "WTI"):
                ranks[s] = ranks.get(s, 0.5) - 0.05
    # Convert ranks to positive scores and combine with inverse volatility.
    raw = {s: max(0.05, 0.35 + ranks.get(s, 0.5)) for s in symbols}
    inv = {s: 1.0 / max(0.08, series[s].get("vol20", 0.25)) for s in symbols}
    sm_inv = sum(inv.values()) or 1.0
    sm_raw = sum(raw.values()) or 1.0
    out = {s: 0.78 * raw[s] / sm_raw + 0.22 * inv[s] / sm_inv for s in symbols}
    # Keep concentration sensible for a 15-asset cross-section and re-normalize.
    out = {s: min(0.16, max(0.015, v)) for s, v in out.items()}
    total = sum(out.values()) or 1.0
    return {s: v / total for s, v in out.items()}


@register_hook
def cross_asset_factor_strategy():
    global _last_decision
    account = get_account_dict() or {}
    watch = [s for s in account.get("watch_list", []) if s in UNIVERSE]
    if len(watch) < 15:
        watch = list(UNIVERSE)
    frames = {s: _data(s, 90) for s in watch}
    dates = []
    for df in frames.values():
        if df is not None and len(df) > 0:
            dates.append(str(df.iloc[-1]["date"]))
    decision_date = max(dates) if dates else None
    if decision_date is None or decision_date == _last_decision:
        return
    # Count market dates locally so the cadence survives hook calls on every day.
    if not hasattr(cross_asset_factor_strategy, "seen"):
        cross_asset_factor_strategy.seen = []
    if decision_date not in cross_asset_factor_strategy.seen:
        cross_asset_factor_strategy.seen.append(decision_date)
    if len(cross_asset_factor_strategy.seen) > 1 and (len(cross_asset_factor_strategy.seen) - 1) % REBALANCE_DAYS != 0:
        return
    _last_decision = decision_date
    ret5 = {}
    for s, df in frames.items():
        if df is None or len(df) < 65:
            continue
        close = [float(x) for x in df["close"].tolist() if x is not None and float(x) > 0]
        if len(close) < 65:
            continue
        rets = [(close[i] / close[i-1] - 1.0) for i in range(1, len(close))]
        r5 = close[-1] / close[-6] - 1.0
        r20 = close[-1] / close[-21] - 1.0
        r60 = close[-1] / close[-61] - 1.0
        v20 = math.sqrt(sum(x*x for x in rets[-20:]) / 20.0) * math.sqrt(252)
        row = {"miner_3_clv_1d": 0.5}
        try:
            hi, lo, cl = float(df.iloc[-1]["high"]), float(df.iloc[-1]["low"]), close[-1]
            row["miner_3_clv_1d"] = (cl - lo) / max(1e-9, hi - lo)
        except Exception:
            pass
        row["short_term_reversal_5d"] = -r5
        row["miner_2_risk_adjusted_momentum_20d"] = r20 / max(0.08 / math.sqrt(252), v20)
        row["ret5"] = r5
        row["vol20"] = v20
        row["spx20"] = r20 if s == "SPX" else 0.0
        row["spx60"] = r60 if s == "SPX" else 0.0
        ret5[s] = r5
        frames[s] = row
    if len(frames) < 15:
        return
    median5 = sorted(ret5.values())[len(ret5)//2]
    for s in frames:
        if isinstance(frames[s], dict):
            frames[s]["peer_median_leadlag_5d"] = ret5.get(s, median5) - median5
    # Fill any missing factor values neutrally and use broad SPX regime values.
    spx20 = frames.get("SPX", {}).get("spx20", 0.0)
    spx60 = frames.get("SPX", {}).get("spx60", 0.0)
    for s in frames:
        frames[s]["spx20"], frames[s]["spx60"] = spx20, spx60
    target = _weights(frames)
    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    total = float(account.get("total_assets", 0) or account.get("net_assets", 0) or 0)
    for s in UNIVERSE:
        pos = positions.get(s, {})
        qty = float(pos.get("quantity", 0) or 0)
        px = float(pos.get("current_price", 0) or 0)
        if qty > 0 and px > 0:
            delta_value = target.get(s, 0.0) * total - qty * px
            if delta_value < -1.0:
                add_order(symbol=s, order_type="SELL", price=px, quantity=min(qty, abs(delta_value) / px))
    for s in UNIVERSE:
        pos = positions.get(s, {})
        qty = float(pos.get("quantity", 0) or 0)
        px = float(pos.get("current_price", 0) or 0)
        if px <= 0:
            px = float(frames[s].get("close", 0) if isinstance(frames[s], dict) else 0)
        if px <= 0:
            continue
        delta_value = target.get(s, 0.0) * total - qty * px
        if delta_value > 1.0:
            add_order(symbol=s, order_type="BUY", price=px, quantity=delta_value / px)

